from pathlib import Path
import json,datetime,hashlib,shutil
R=Path(__file__).resolve().parents[1];Q=R/'round7';assert not (Q/'state/round_status.json').exists()
for d in ['configs','state','reports','tools','inputs','graphs','rtl','src','logs','build','results/hardware']:(Q/d).mkdir(parents=True,exist_ok=True)
def load(p):return json.loads(p.read_text())
def dump(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf-8')
cases=[dict(name='sqrt12',kind='sqrt',bits=12,t=0,domain_bits=12,budget=1,clock_ns=10.0,graph_round=4,physical_round=5,physical_case='sqrt12_c10p0'),dict(name='sqrt16',kind='sqrt',bits=16,t=0,domain_bits=16,budget=1,clock_ns=16.667,graph_round=4,physical_round=5,physical_case='sqrt16_c16p667')]
cases += [dict(c,graph_round=6,physical_round=6,physical_case=c['name'])for c in load(R/'round6/configs/plan.json')['cases']]
plan=dict(round=7,registered=datetime.datetime.now().astimezone().isoformat(),question='Does a conventional whole-combinational-network ABC flow remove the apparent advantage of macro-preserving relation resynthesis?',cases=cases,methods=['abc_region','abc_global','relation'],baselines=['abc_region','abc_global'],innovations=['relation'],method_changes='None. Relation and regional ABC results are inherited by exact RTL identity and matching registered physical constraints; not new runs.',global_abc='Expand CARRY4 and INV into exact Boolean logic, preserve all registers/constants; resynthesize the entire combinational network using the same pinned strash; dc2; if -K 6; mfs2 recipe. No macro-boundary independence assumption. Restore register interfaces, verify whole-combinational CEC and full effective input domain, vendor HDL, then physical flow.',physical='Same part xc7a100tcsg324-1, route_clocked.tcl, DSP forbidden, fixed case clocks and 2ns IO. Six new physical builds, no directive or clock search.',interpretation='Global ABC is an abstraction diagnostic: it may trade dedicated CARRY4 resources for LUTs. It is not a claim to reproduce every macro-aware or recent dual-output mapper. Report both area and timing; no speedup claim from an unclosed implementation.',stop='Complete the six fixed new cases and inheritance checks, analyze and score; no additional method or benchmark in this round.',score=dict(innovation=25,physical_gain=25,problem_coverage=20,correctness=20,cost=10))
dump(Q/'configs/plan.json',plan);hashes={};inherited=[]
for c in cases:
 n=c['name'];gr=R/f'round{c["graph_round"]}';pr=R/f'round{c["physical_round"]}';src=gr/f'graphs/{n}_seed.json';shutil.copy2(src,Q/f'graphs/{n}_seed.json');hashes[str(src)]=hashlib.sha256(src.read_bytes()).hexdigest()
 ppa=load(pr/'results/hardware/ppa.json');manifest=load(pr/'rtl/design_manifest.json')
 for m in ['abc_exact','relation']:
  entry=next(e for e in manifest if e['case']==c['physical_case']and e['method']==m);rtl=pr/f'rtl/{entry["top"]}.v';file_sha=hashlib.sha256(rtl.read_bytes()).hexdigest();text_sha=hashlib.sha256(rtl.read_text().encode()).hexdigest();assert text_sha==entry['sha256'];assert file_sha==load(pr/'state/evidence_hashes.json')[rtl.relative_to(pr).as_posix()];target=entry['duplicate_of']or entry['top'];row=next(x for x in ppa if x['case']==c['physical_case']and x['top']==target);assert row['clock_ns']==c['clock_ns'] and row['DSP']==0
  inherited.append(dict(case=n,method='abc_region'if m=='abc_exact'else m,source_round=c['physical_round'],source_case=c['physical_case'],physical_result=row,rtl=str(rtl),rtl_file_sha256=file_sha,rtl_normalized_text_sha256=text_sha,new_run=False));hashes[str(rtl)]=file_sha
 hashes[str(pr/'results/hardware/ppa.json')]=hashlib.sha256((pr/'results/hardware/ppa.json').read_bytes()).hexdigest()
 oldxdc=pr/f'rtl/{c["physical_case"]}.xdc';shutil.copy2(oldxdc,Q/f'rtl/{n}.xdc');hashes[str(oldxdc)]=hashlib.sha256(oldxdc.read_bytes()).hexdigest()
shutil.copy2(R/'round6/inputs/abc_executable',Q/'inputs/abc_executable');hashes[str(Q/'inputs/abc_executable')]=hashlib.sha256((Q/'inputs/abc_executable').read_bytes()).hexdigest();hashes[str(R/'tools/route_clocked.tcl')]=hashlib.sha256((R/'tools/route_clocked.tcl').read_bytes()).hexdigest();dump(Q/'state/input_hashes.json',hashes);dump(Q/'state/inherited_results.json',inherited);dump(Q/'state/progress.json',dict(phase='REGISTERED',round=7));dump(Q/'state/round_status.json',dict(status='REGISTERED',round=7))
campaign=load(R/'state/campaign.json');campaign.update(status='ROUND7_REGISTERED',active_round=7,root=str(Q),latest_progress='round7/state/progress.json');dump(R/'state/campaign.json',campaign);print('Round7 registered',len(cases),'new physical jobs,',len(inherited),'inherited results')
